const n = s.length;
const P1 = 94905991, P2 = 94905989;
const B1 = 1000 + Math.floor(Math.random() * (P1 - 2000));
const B2 = 1000 + Math.floor(Math.random() * (P2 - 2000));
const h1 = new Array(n + 1).fill(0), h2 = new Array(n + 1).fill(0);
const p1 = new Array(n + 1).fill(1), p2 = new Array(n + 1).fill(1);
for (let i = 0; i < n; i++) {
  const c = s.charCodeAt(i);
  h1[i + 1] = (h1[i] * B1 + c) % P1;
  h2[i + 1] = (h2[i] * B2 + c) % P2;
  p1[i + 1] = (p1[i] * B1) % P1;
  p2[i + 1] = (p2[i] * B2) % P2;
}
function hasRepeat(L) {
  const seen = new Set();
  for (let i = 0; i + L <= n; i++) {
    const x = ((h1[i + L] - (h1[i] * p1[L]) % P1) % P1 + P1) % P1;
    const y = ((h2[i + L] - (h2[i] * p2[L]) % P2) % P2 + P2) % P2;
    const key = x * P2 + y;
    if (seen.has(key)) return true;
    seen.add(key);
  }
  return false;
}
let lo = 0, hi = n - 1;
while (lo < hi) {
  const mid = (lo + hi + 1) >> 1;
  if (hasRepeat(mid)) lo = mid; else hi = mid - 1;
