import java.util.*;
import java.io.*;

public class Main {
    static final long M1 = 1_000_000_007L, M2 = 998_244_353L;
    static long[] h1, h2, p1, p2;
    static int n;

    static boolean hasRepeat(int L) {
        HashSet<Long> seen = new HashSet<>();
        for (int i = 0; i + L <= n; i++) {
            long x = ((h1[i + L] - h1[i] * p1[L]) % M1 + M1) % M1;
            long y = ((h2[i + L] - h2[i] * p2[L]) % M2 + M2) % M2;
            if (!seen.add(x * M2 + y)) return true;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        n = s.length();
        Random rnd = new Random();
        long B1 = 1000 + rnd.nextInt((int) M1 - 2000);
        long B2 = 1000 + rnd.nextInt((int) M2 - 2000);
        h1 = new long[n + 1]; h2 = new long[n + 1];
        p1 = new long[n + 1]; p2 = new long[n + 1];
        p1[0] = 1; p2[0] = 1;
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i);
            h1[i + 1] = (h1[i] * B1 + c) % M1;
            h2[i + 1] = (h2[i] * B2 + c) % M2;
            p1[i + 1] = p1[i] * B1 % M1;
            p2[i + 1] = p2[i] * B2 % M2;
        }
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (hasRepeat(mid)) lo = mid; else hi = mid - 1;
        }
        System.out.println(lo);
    }
}

