#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll M1 = 1000000007LL, M2 = 998244353LL;
int n;
vector<ll> h1, h2, p1, p2;
bool hasRepeat(int L) {
    vector<ll> keys;
    for (int i = 0; i + L <= n; i++) {
        ll x = ((h1[i + L] - h1[i] * p1[L]) % M1 + M1) % M1;
        ll y = ((h2[i + L] - h2[i] * p2[L]) % M2 + M2) % M2;
        keys.push_back(x * M2 + y);
    }
    sort(keys.begin(), keys.end());
    return adjacent_find(keys.begin(), keys.end()) != keys.end();
}
int main() {
    string s;
    cin >> s;
    n = s.size();
    mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());
    ll B1 = 1000 + rng() % (M1 - 2000), B2 = 1000 + rng() % (M2 - 2000);
    h1.assign(n + 1, 0); h2.assign(n + 1, 0);
    p1.assign(n + 1, 1); p2.assign(n + 1, 1);
    for (int i = 0; i < n; i++) {
        h1[i + 1] = (h1[i] * B1 + s[i]) % M1;
        h2[i + 1] = (h2[i] * B2 + s[i]) % M2;
        p1[i + 1] = p1[i] * B1 % M1;
        p2[i + 1] = p2[i] * B2 % M2;
    }
    int lo = 0, hi = n - 1;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (hasRepeat(mid)) lo = mid; else hi = mid - 1;
    }
    cout << lo << "\n";
    return 0;
}
